// Init Inputs and Global Telemetry
const rss_feeds = [
  "https://hnrss.org/frontpage",
  "https://www.nasa.gov/rss/dyn/breaking_news.rss"
];
const topics = [
  "agentic workflows",
  "mcp protocol",
  "vector databases",
  "prompt injection",
  "postgres embeddings"
];
const config = {
  cache_ttl_minutes: 60,
  dedupe_ttl_days: 14,
  min_score: 8,
  max_items_total: 35,
  max_per_source: 12,
  max_per_topic: 6,
  enable_llm_summary: true,
  retry_max: 2,
  retry_backoff_ms: 800,
  timeout_ms: 12000,
  ZAI_API_KEY: $env.ZAI_API_KEY || "",
  ZAI_BASE_URL: $env.ZAI_BASE_URL || "https://api.z.ai/api/paas/v4",
  ZAI_MODEL: $env.ZAI_MODEL || "glm-5"
};

// Init Telemetry
const st = $getWorkflowStaticData('global');
st.runs = (st.runs || 0) + 1;

return [{ json: { rss_feeds, topics, config } }];

// Normalize RSS Items - rssFeedRead outputs items directly
const items = $input.all();
const out = [];

for(const item of items) {
  const feedUrl = item.json.rss_url;
  // rssFeedRead returns items array directly in item.json
  const entries = Array.isArray(item.json) ? item.json : (item.json.items || []);

  for(const entry of entries) {
    const title = entry?.title || "Untitled";
    const url = entry?.link || entry?.url || entry?.guid || "";
    if(!url) continue;

    out.push({
      json: {
        source: "rss",
        topic: null,
        title,
        url,
        published_at: entry?.pubDate || entry?.isoDate || entry?.published || null,
        raw_score: 5,
        score: 5,
        summary_raw: entry?.contentSnippet || entry?.description || entry?.summary || null,
        summary: null,
        meta: {
          author: entry?.creator || entry?.author || null,
          venue: feedUrl ? new URL(feedUrl).hostname : 'rss',
          cached: false,
          http_status: null
        }
      }
    });
  }
}

if (out.length === 0) {
  return [{ json: { __empty: true, __stream: 'rss' } }];
}
return out;

// Cache Gate Logic
const item = $input.first();
const topic = item.json.topic;
const config = $('Init').first().json.config;
const st = $getWorkflowStaticData('global');

if(!st.cache) st.cache = {};
const now = Date.now();
const ttl = config.cache_ttl_minutes * 60 * 1000;

// Prune old cache entries
for(const k in st.cache) {
  if(now - st.cache[k].ts_epoch_ms > ttl) delete st.cache[k];
}

const cached = st.cache[topic];
if(cached && (now - cached.ts_epoch_ms <= ttl)) {
  return [{ json: { topic, config, cache_hit: true, cached_items: cached.items || [] } }];
}

return [{ json: { topic, config, cache_hit: false } }];

const data = $input.first().json;
const items = data.cached_items || [];

if (items.length === 0) {
  return [{ json: { __empty: true, __stream: 'cache', __meta: { cached_hits: 0 } } }];
}

return items.map(i => ({
  json: { ...i, meta: { ...i.meta, cached: true }, __meta: { cached_hits: items.length } }
}));

const topic = $('Cache Gate').first().json.topic;
const data = $input.first().json;
const hits = data?.hits || [];

if (!hits || hits.length === 0) {
  return [{ json: { __empty: true, __src: 'hn', __meta: { failed_calls: data ? 0 : 1 } } }];
}

return hits.map(h => ({
  json: {
    source: "hn",
    topic,
    title: h.title || "Untitled",
    url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`,
    published_at: h.created_at ? new Date(h.created_at).toISOString() : null,
    raw_score: (h.points || 0) + (h.num_comments || 0),
    score: (h.points || 0) + (h.num_comments || 0),
    summary_raw: null,
    summary: null,
    meta: { author: h.author || null, venue: "HackerNews", cached: false, http_status: null }
  }
}));

const topic = $('Cache Gate').first().json.topic;
const data = $input.first().json;
const items = data?.items || [];

if (!items || items.length === 0) {
  return [{ json: { __empty: true, __src: 'github', __meta: { failed_calls: data ? 0 : 1 } } }];
}

return items.map(i => ({
  json: {
    source: "github",
    topic,
    title: i.full_name || i.name || "Untitled",
    url: i.html_url || "",
    published_at: i.updated_at || null,
    raw_score: (i.stargazers_count||0) + (i.forks_count||0),
    score: (i.stargazers_count||0) + (i.forks_count||0),
    summary_raw: i.description || null,
    summary: null,
    meta: { author: i.owner?.login || null, venue: "GitHub", cached: false, http_status: null }
  }
}));

const topic = $('Cache Gate').first().json.topic;
const data = $input.first().json;
const items = data?.message?.items || [];

if (!items || items.length === 0) {
  return [{ json: { __empty: true, __src: 'crossref', __meta: { failed_calls: data ? 0 : 1 } } }];
}

return items.map(i => {
  const title = (i.title && i.title[0]) || "Untitled";
  const url = i.URL || (i.DOI ? `https://doi.org/${i.DOI}` : "");
  return {
    json: {
      source: "crossref",
      topic,
      title,
      url,
      published_at: i.published?.['date-parts']?.[0]?.join('-') || null,
      raw_score: 20 + (i['is-referenced-by-count']||0),
      score: 20 + (i['is-referenced-by-count']||0),
      summary_raw: i.abstract || i.subtitle || null,
      summary: null,
      meta: { author: null, venue: i['container-title']?.[0] || "Crossref", cached: false, http_status: null }
    }
  };
});

const allInputs = $input.all();
const topic = $('Cache Gate').first().json.topic;
const st = $getWorkflowStaticData('global');

if(!st.cache) st.cache = {};

// Collect valid items (skip __empty markers)
let failedCalls = 0;
const validItems = [];

for (const item of allInputs) {
  const i = item.json;
  if (i.__empty) {
    if (i.__meta?.failed_calls) failedCalls += i.__meta.failed_calls;
    continue;
  }
  validItems.push(i);
}

// Save to cache (even if empty)
st.cache[topic] = { ts_epoch_ms: Date.now(), items: validItems };

if (validItems.length === 0) {
  return [{ json: { __empty: true, topic, __meta: { api_calls: 3, failed_calls: failedCalls || 3 } } }];
}

return validItems.map(i => ({ json: { ...i, __meta: { api_calls: 3, failed_calls: 0 } } }));

const init = $('Init').first().json;
const config = init.config;
const st = $getWorkflowStaticData('global');
if(!st.seen) st.seen = {};

const now = Date.now();
const dedupeTtl = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;

// Prune seen
for(const k in st.seen) {
  if(now - st.seen[k] > dedupeTtl) delete st.seen[k];
}

// Collect all items and count cache misses
let candidates = 0;
let cachedHits = 0;
let apiCalls = 0;
let failedCalls = 0;
const allItems = [];

for (const item of $input.all()) {
  const i = item.json;

  // Skip empty markers but extract stats
  if (i.__empty) {
    if (i.__meta?.failed_calls) failedCalls += i.__meta.failed_calls;
    continue;
  }

  candidates++;

  // Count cached hits
  if (i.meta?.cached) cachedHits++;

  // Count API calls from metadata
  if (i.__meta?.api_calls) apiCalls += i.__meta.api_calls;
  if (i.__meta?.failed_calls) failedCalls += i.__meta.failed_calls;

  allItems.push(i);
}

// Dedupe
const seen = [];
for (const i of allItems) {
  if(!i.url) continue;
  if(st.seen[i.url]) continue;
  st.seen[i.url] = now;
  seen.push(i);
}

// Filter Score
const filtered = seen.filter(i => i.score >= config.min_score);

// Sort by score first (best items survive caps)
filtered.sort((a,b) => b.score - a.score);

// Diversity Caps (check BEFORE incrementing)
const sourceCounts = {};
const topicCounts = {};
const capped = [];

for (const i of filtered) {
  const s = i.source || 'unknown';
  const t = i.topic || 'null';

  // Check caps first
  if((sourceCounts[s] || 0) >= config.max_per_source) continue;
  if((topicCounts[t] || 0) >= config.max_per_topic) continue;

  // Then increment
  sourceCounts[s] = (sourceCounts[s] || 0) + 1;
  topicCounts[t] = (topicCounts[t] || 0) + 1;
  capped.push(i);
}

// Final slice
const items = capped.slice(0, config.max_items_total);

// Stats
const stats = {
  candidates_total: candidates,
  new_items: items.length,
  cached_hits: cachedHits,
  api_calls: apiCalls,
  failed_calls: failedCalls,
  by_source: items.reduce((acc, i) => { acc[i.source] = (acc[i.source]||0)+1; return acc; }, {})
};

return [{ json: { config, topics: init.topics, stats, items, run_id: st.runs, generated_at: new Date().toISOString() } }];

const ctx = $input.first().json;
const top12 = (ctx.items || []).slice(0, 12).map(i => `URL: ${i.url}\nTitle: ${i.title}\nScore: ${i.score}`).join('\n\n');
const prompt = `Generate a 1 sentence summary for each of the following items. Return STRICT JSON:\n{"summaries":[{"url":"...","summary":"1 sentence"}]}\n\nItems:\n${top12}`;
return [{ json: {
  // Preserve base data
  __baseData: {
    config: ctx.config,
    topics: ctx.topics,
    stats: ctx.stats,
    run_id: ctx.run_id,
    generated_at: ctx.generated_at,
    items: ctx.items
  },
  config: ctx.config,
  llm_body: { messages: [{ role: 'user', content: prompt }] }
} }];

// CRITICAL: Read base data from Prepare LLM (not from HTTP response)
const prepNode = $('Prepare LLM').first().json;
const baseData = prepNode.__baseData || prepNode;
const resp = $input.first().json;

let summaryMap = {};

try {
  let content = resp?.choices?.[0]?.message?.content;
  if(content) {
    const parsed = JSON.parse(content);
    // Support both formats: {summaries:[]} and {"url":"summary"}
    if (Array.isArray(parsed.summaries)) {
      parsed.summaries.forEach(s => { if(s.url && s.summary) summaryMap[s.url] = s.summary; });
    } else if (typeof parsed === 'object') {
      for (const [url, summary] of Object.entries(parsed)) {
        if (typeof summary === 'string') summaryMap[url] = summary;
      }
    }
  }
} catch(e) { console.error('LLM parse error:', e); }

const items = (baseData.items || []).map(i => ({
  ...i,
  summary: summaryMap[i.url] || i.summary_raw || i.title
}));

return [{ json: {
  config: baseData.config,
  topics: baseData.topics,
  stats: baseData.stats,
  run_id: baseData.run_id,
  generated_at: baseData.generated_at,
  items
} }];

const ctx = $input.first().json;
const items = (ctx.items || []).map(i => ({
  ...i,
  summary: i.summary_raw || i.title
}));
return [{ json: { ...ctx, items } }];

const data = $input.first().json;
// QA Checks
if(!data.items || !Array.isArray(data.items)) throw new Error('Invalid items');
for(const i of data.items) {
  if(typeof i.url !== 'string' || i.url === '') throw new Error('Empty URL');
  if(typeof i.score !== 'number') throw new Error('Invalid score');
}
const str = JSON.stringify(data);
if(str.includes('{{')) throw new Error('Contains {{');
return [{ json: data }];

const data = $input.first().json;
const bySource = {};
(data.items || []).forEach(i => {
  if(!bySource[i.source]) bySource[i.source] = [];
  bySource[i.source].push(i);
});

let md = `# QuorumPulse Signal Pack\n\n`;
md += `**Generated:** ${data.generated_at}\n`;
md += `**Stats:** ${data.stats?.new_items || 0} items, ${data.stats?.cached_hits || 0} cached, ${data.stats?.api_calls || 0} API calls\n\n`;

for(const [src, items] of Object.entries(bySource)) {
  md += `## ${src.toUpperCase()}\n`;
  items.forEach(i => {
    md += `- [${i.score}] ${i.title}\n  > ${i.summary || 'No summary'}\n  Link: ${i.url}\n`;
  });
  md += `\n`;
}

return [{ json: { ...data, digest_markdown: md } }];
